func:
// Ghi số giây mở cửa. Khách chưa có phiên thì trả lại số cũ, không ghi đè.
let socketId = msg._client && msg._client.socketId;
if (socketId) {
    let phien = global.get('phien') || {};
    if (!phien[socketId]) {
        node.status({ fill: 'grey', shape: 'ring', text: 'bỏ qua, chưa đăng nhập' });
        return { _client: msg._client, payload: flow.get('feedDurationS') ?? 1.5 };
    }
}
flow.set('feedDurationS', msg.payload);
node.status({});
return null;

// Đã có global.phien thì gửi feeder/cmd/feed. retain = false để hộp không tự cho ăn khi nối lại.
let socketId = msg._client && msg._client.socketId;
let phien = global.get('phien') || {};
if (!socketId || !phien[socketId]) {
    node.status({ fill: 'red', shape: 'ring', text: 'chưa đăng nhập' });
    return [null, {
        _client: msg._client,
        payload: 'Chưa đăng nhập, không gửi lệnh cho ăn'
    }];
}

// Đổi giây trên thanh trượt sang duration_ms, giữ trong khoảng firmware cho phép.
let giay = Number(flow.get('feedDurationS') ?? 1.5);
let durationMs = Math.round(Math.min(5, Math.max(0.2, giay)) * 1000);

// retain=false: nếu retain, mỗi lần ESP32 kết nối lại sẽ tự cho ăn thêm.
let lenh = { topic: 'feeder/cmd/feed', payload: { duration_ms: durationMs }, qos: 0, retain: false };
let hienThi = { payload: 'Đã gửi lệnh, đang chờ hộp...' };
node.status({ fill: 'green', shape: 'dot', text: 'đã gửi lệnh' });
return [lenh, hienThi];

// Đọc feeder/status rồi viết câu cho ô trạng thái.
let s = msg.payload;
if (!s || s.event !== 'feed') return null;

let giay = (s.duration_ms / 1000).toFixed(1);
let text;
let ketThuc = false;   // true: ngừng đếm 8 s
if (s.result === 'opening') {
    text = `Đang mở cửa (${giay} s)`;
} else if (s.result === 'done') {
    text = `Đã cho ăn xong (${giay} s)`;
    ketThuc = true;
} else if (s.result === 'rejected' && s.reason === 'busy') {
    // Lệnh trước vẫn đang chạy nên vẫn tiếp tục chờ done của lệnh đó.
    text = 'Cửa đang mở, lệnh mới bị bỏ qua';
} else if (s.result === 'rejected') {
    text = 'Hộp từ chối lệnh không hợp lệ';
    ketThuc = true;
} else {
    return null;
}
return [{ payload: text }, ketThuc ? { reset: true } : null];

// Đổi tin online của ESP32 thành chữ Online hoặc Offline.
msg.payload = msg.payload && msg.payload.online ? 'Online' : 'Offline';
return msg;

// Ghi công tắc ntfy. Khách chưa đăng nhập thì trả lại trạng thái cũ.
let socketId = msg._client && msg._client.socketId;
if (socketId) {
    let phien = global.get('phien') || {};
    if (!phien[socketId]) {
        node.status({ fill: 'grey', shape: 'ring', text: 'bỏ qua, chưa đăng nhập' });
        return { _client: msg._client, payload: flow.get('ntfyBat') !== false };
    }
}
flow.set('ntfyBat', msg.payload);
node.status({});
return null;

// Dưới 20% thì báo một lần. Mức lên lại từ 25% mới được báo tiếp.
let NGUONG = 20;
let MUC_BAO_LAI = 25;

let level = Number(msg.payload && msg.payload.level);
if (!Number.isFinite(level)) return null;

if (level >= MUC_BAO_LAI) {
    flow.set('ntfyDaBao', false);
    return null;
}
if (level >= NGUONG) return null;
if (flow.get('ntfyBat') === false) return null;
if (flow.get('ntfyDaBao')) return null;

let topic = env.get('NTFY_TOPIC');
if (!topic) {
    node.warn('Chưa đặt NTFY_TOPIC');
    return null;
}
flow.set('ntfyDaBao', true);
return {
    method: 'POST',
    url: env.get('NTFY_URL') || 'https://ntfy.sh',
    headers: { 'Content-Type': 'application/json' },
    // Dạng JSON cho phép tiêu đề có dấu tiếng Việt.
    payload: {
        topic,
        title: 'Sắp hết thức ăn',
        message: `Hộp cho ăn chỉ còn ${Math.round(level)}%. Hãy châm thêm thức ăn.`,
        priority: 4,
        tags: ['warning']
    }
};

// Gửi ntfy lỗi thì bỏ cờ đã báo, lần đo sau thử lại.
if (msg.statusCode === 200) {
    node.status({ fill: 'green', shape: 'dot', text: 'đã gửi' });
    return null;
}
flow.set('ntfyDaBao', false);
node.status({ fill: 'red', shape: 'ring', text: 'lỗi ' + (msg.statusCode || 'mạng') });
node.warn('Gửi ntfy thất bại: ' + (msg.statusCode || 'lỗi mạng'));
return null;

// Lấy mức trong 24 giờ, mới nhất trước, tối đa 1000 dòng.
let url = env.get('SUPABASE_URL');
let key = env.get('SUPABASE_KEY');

if (!url || !key) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'chưa cấu hình Supabase' });
    return null;
}
let tu = new Date(Date.now() - 24 * 3600 * 1000).toISOString();
// Lấy mới nhất trước: Supabase giới hạn 1000 dòng, sắp tăng dần sẽ mất phần mới nhất.
let q = 'select=created_at,level&event=eq.level'
    + '&created_at=gte.' + encodeURIComponent(tu)
    + '&order=created_at.desc&limit=1000';
return {
    method: 'GET',
    url: url + '/rest/v1/feeder_events?' + q,
    headers: { apikey: key, Authorization: 'Bearer ' + key },
    payload: null
};

// Đảo thành thời gian tăng dần rồi đưa sang biểu đồ.
if (msg.statusCode !== 200 || !Array.isArray(msg.payload)) {
    // Giữ nguyên biểu đồ cũ thay vì xóa trắng khi mất mạng.
    node.status({ fill: 'red', shape: 'ring', text: 'lỗi ' + (msg.statusCode || 'dữ liệu') });
    node.warn('Đọc lịch sử Supabase thất bại: ' + (msg.statusCode || 'dữ liệu sai'));
    return null;
}
// Đảo lại theo thời gian tăng dần để vẽ đường.
let diem = msg.payload
    .map(r => ({ time: new Date(r.created_at).getTime(), level: r.level }))
    .filter(d => Number.isFinite(d.time) && Number.isFinite(d.level))
    .reverse();
node.status({ fill: 'green', shape: 'dot', text: diem.length + ' điểm' });
return { payload: diem, action: 'replace', topic: 'Mức thức ăn' };

// Chỉ người đã đăng nhập mới được hỏi. Sau đó lấy mức mới nhất.
let socketId = msg._client && msg._client.socketId;
let phien = global.get('phien') || {};
if (!socketId || !phien[socketId]) {
    msg.payload = 'Chưa đăng nhập.';
    msg.traLoi = true;
    return [null, msg];
}

let url = env.get('SUPABASE_URL');
let key = env.get('SUPABASE_KEY');

let cau = String(msg.payload || '').trim().slice(0, 500);
if (!cau) return [null, null];

if (!url || !key || !env.get('GEMINI_API_KEY')) {
    node.warn('Thiếu SUPABASE_URL, SUPABASE_KEY hoặc GEMINI_API_KEY');
    msg.payload = 'Chatbot chưa được cấu hình.';
    msg.traLoi = true;
    return [null, msg];
}
msg.cauHoi = cau;
msg.method = 'GET';
msg.url = url + '/rest/v1/feeder_events?select=created_at,level&event=eq.level&order=created_at.desc&limit=1';
msg.headers = { apikey: key, Authorization: 'Bearer ' + key };
msg.payload = null;
return [msg, null];

// Giữ mức vừa đọc, rồi lấy lịch sử cho ăn.
let url = env.get('SUPABASE_URL');
let key = env.get('SUPABASE_KEY');

if (msg.statusCode !== 200 || !Array.isArray(msg.payload)) {
    node.warn('Đọc mức thức ăn thất bại: ' + msg.statusCode);
    msg.payload = 'Hiện không đọc được dữ liệu của hộp, bạn thử lại sau nhé.';
    msg.traLoi = true;
    return [null, msg];
}
msg.mucMoiNhat = msg.payload[0] || null;
msg.method = 'GET';
msg.url = url + '/rest/v1/feeder_events?select=created_at,duration_ms&event=eq.feed&order=created_at.desc&limit=100';
msg.headers = { apikey: key, Authorization: 'Bearer ' + key };
msg.payload = null;
return [msg, null];

// Gửi Gemini đúng số liệu đã đọc. Không có số thì ghi chưa có, không để model tự đoán.
if (msg.statusCode !== 200 || !Array.isArray(msg.payload)) {
    node.warn('Đọc lịch sử cho ăn thất bại: ' + msg.statusCode);
    msg.payload = 'Hiện không đọc được dữ liệu của hộp, bạn thử lại sau nhé.';
    msg.traLoi = true;
    return [null, msg];
}
let TZ = 'Asia/Ho_Chi_Minh';
let gio = s => new Date(s).toLocaleString('vi-VN', { timeZone: TZ });
let ngay = d => new Date(d).toLocaleDateString('en-CA', { timeZone: TZ });

let homNay = ngay(Date.now());
let feeds = msg.payload;
let soLanHomNay = feeds.filter(f => ngay(f.created_at) === homNay).length;
let muc = msg.mucMoiNhat;

// Chỉ đưa dữ liệu thật; chưa có thì ghi rõ để Gemini không tự đoán.
let duLieu = [
    'Thời điểm hiện tại: ' + gio(Date.now()),
    muc ? `Mức thức ăn mới nhất: ${muc.level}% (đo lúc ${gio(muc.created_at)})` : 'Mức thức ăn: chưa có dữ liệu',
    feeds.length ? `Lần cho ăn gần nhất: ${gio(feeds[0].created_at)}, mở cửa ${feeds[0].duration_ms / 1000} giây` : 'Lần cho ăn gần nhất: chưa có dữ liệu',
    'Số lần cho ăn hôm nay: ' + soLanHomNay
].join('\n');

let model = env.get('GEMINI_MODEL') || 'gemini-3.8-flash';
let base = env.get('GEMINI_BASE_URL') || 'https://generativelanguage.googleapis.com';
msg.method = 'POST';
msg.url = `${base}/v1beta/models/${encodeURIComponent(model)}:generateContent`;
msg.headers = { 'Content-Type': 'application/json', 'x-goog-api-key': env.get('GEMINI_API_KEY') };
msg.payload = {
    systemInstruction: { parts: [{ text:
        'Bạn là trợ lý của hộp cho thú cưng ăn tự động. Trả lời ngắn gọn bằng tiếng Việt, chỉ dựa trên DỮ LIỆU HỆ THỐNG được cung cấp. '
        + 'Không có dữ liệu thì nói là chưa có, không được đoán. Bạn chỉ trả lời thông tin, không điều khiển được hộp. '
        + 'Câu hỏi không liên quan đến hộp cho ăn thì lịch sự từ chối.'
    }] },
    contents: [{ role: 'user', parts: [{ text: 'DỮ LIỆU HỆ THỐNG:\n' + duLieu + '\n\nCÂU HỎI CỦA CHỦ NUÔI:\n' + msg.cauHoi }] }],
    generationConfig: { maxOutputTokens: 1024 }
};
return msg;

// Lấy chữ Gemini trả về và hiện trong khung chat.
msg.traLoi = true;
if (msg.statusCode === 429) {
    node.warn('Gemini báo 429: hết hạn mức hoặc model không có gói miễn phí');
    msg.payload = 'Chatbot đang quá tải, bạn thử lại sau ít phút nhé.';
    return msg;
}
let parts = msg.statusCode === 200 && msg.payload && msg.payload.candidates
    && msg.payload.candidates[0] && msg.payload.candidates[0].content && msg.payload.candidates[0].content.parts;
let text = Array.isArray(parts) ? parts.map(p => p.text || '').join('').trim() : '';
if (!text) {
    node.warn('Gemini không trả lời được, mã ' + msg.statusCode);
    msg.payload = 'Mình chưa trả lời được câu này, bạn thử lại nhé.';
    return msg;
}
msg.payload = text;
return msg;
